from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def nilai_uang(teks: str) -> Decimal:
    if not isinstance(teks, str) or not 1 <= len(teks) <= 40:
        raise ValueError('Gunakan teks angka dengan panjang 1..40.')
    try:
        nilai = Decimal(teks)
        if not nilai.is_finite() or not Decimal('0') <= nilai <= Decimal('1000000000'):
            raise ValueError('Nilai harus terbatas dan berada pada 0..1 miliar.')
        return nilai.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except InvalidOperation as exc:
        raise ValueError('Angka desimal tidak valid.') from exc


def total_baris(harga: str, jumlah: int) -> Decimal:
    if type(jumlah) is not int or not 1 <= jumlah <= 1000:
        raise ValueError('Jumlah harus integer 1..1000.')
    return nilai_uang(harga) * jumlah


if __name__ == '__main__':
    print(Decimal('0.1') + Decimal('0.2'))
    print(nilai_uang('12.345'))
    print(total_baris('12.345', 2))

import argparse


def jumlah_valid(teks):
    try:
        nilai = int(teks)
    except ValueError as exc:
        raise argparse.ArgumentTypeError('Harus berupa integer.') from exc
    if not 1 <= nilai <= 100:
        raise argparse.ArgumentTypeError('Jumlah harus 1..100.')
    return nilai


def buat_parser():
    parser = argparse.ArgumentParser(description='Ringkasan perangkat latihan.')
    parser.add_argument('--nama', required=True, help='Nama perangkat, bukan secret.')
    parser.add_argument('--jumlah', type=jumlah_valid, default=1)
    return parser


def main(argv=None):
    args = buat_parser().parse_args(argv)
    nama = args.nama.strip()
    if not nama:
        buat_parser().error('Nama tidak boleh kosong.')
    print(f'{nama}: {args.jumlah} unit')


if __name__ == '__main__':
    main()

def buat_prefix(data):
    prefix = [0]
    for nilai in data:
        prefix.append(prefix[-1] + nilai)
    return prefix


def jumlah_rentang(prefix, kiri, kanan):
    # Prefix berasal dari buat_prefix; interval [kiri, kanan).
    if type(kiri) is not int or type(kanan) is not int:
        raise ValueError('Batas harus integer.')
    if not 0 <= kiri <= kanan < len(prefix):
        raise ValueError('Rentang di luar data.')
    return prefix[kanan] - prefix[kiri]


if __name__ == '__main__':
    prefix = buat_prefix([4, 2, -1, 5])
    print(prefix)
    print(jumlah_rentang(prefix, 1, 4))
    print(jumlah_rentang(prefix, 2, 2))

def maksimum_jendela(data, k):
    if type(k) is not int or not 1 <= k <= len(data):
        raise ValueError('K harus 1..panjang data.')
    total = sum(data[:k])
    terbaik = total  # Bukan 0: semua jumlah bisa negatif.
    posisi = 0
    for kanan in range(k, len(data)):
        total += data[kanan] - data[kanan - k]
        if total > terbaik:
            terbaik, posisi = total, kanan - k + 1
    return posisi, terbaik


if __name__ == '__main__':
    print(maksimum_jendela([4, 2, -1, 5], 2))
    print(maksimum_jendela([-5, -2, -4], 2))

from typing import Protocol
import math


class SumberSuhu(Protocol):
    def baca(self) -> float: ...


class SensorLatihan:
    def baca(self) -> float:
        return 28.5


class SensorCadangan:
    def baca(self) -> float:
        return 31.0


def laporan(sumber: SumberSuhu) -> str:
    suhu = sumber.baca()
    if isinstance(suhu, bool) or not isinstance(suhu, (int, float)) or not math.isfinite(suhu):
        raise ValueError('Suhu harus angka terbatas.')
    return f'Suhu: {suhu:.1f} C'


if __name__ == '__main__':
    print(laporan(SensorLatihan()))
    print(laporan(SensorCadangan()))

from io import StringIO


class CatatanSementara:
    def __enter__(self):
        self.buffer = StringIO()
        return self.buffer

    def __exit__(self, jenis_error, nilai_error, traceback):
        self.buffer.close()
        return False  # Error tetap diteruskan ke pemanggil.


if __name__ == '__main__':
    catatan = CatatanSementara()
    try:
        with catatan as buffer:
            buffer.write('Mulai pemeriksaan')
            print(buffer.getvalue())
            raise ValueError('Sensor latihan gagal')
    except ValueError:
        print('Error ditangani pemanggil')
    print('Buffer tertutup:', catatan.buffer.closed)

import hashlib
import json
from typing import Annotated
from fastapi import FastAPI, Header, Response
from fastapi.testclient import TestClient


def create_app():
    app = FastAPI()

    @app.get('/katalog')
    def katalog(if_none_match: Annotated[str | None, Header()] = None):
        body = json.dumps({'materi': ['Python', 'Web']}, ensure_ascii=False, separators=(',', ':')).encode()
        etag = '"' + hashlib.sha256(body).hexdigest() + '"'
        headers = {'ETag': etag, 'Cache-Control': 'private, max-age=0, must-revalidate'}
        # Nilai ETag server ini hanya hash heksadesimal, tanpa koma.
        cocok = if_none_match is not None and any(
            item.strip() == '*' or item.strip().removeprefix('W/') == etag
            for item in if_none_match.split(',')
        )
        if cocok:
            return Response(status_code=304, headers=headers)
        return Response(content=body, media_type='application/json', headers=headers)

    return app


if __name__ == '__main__':
    with TestClient(create_app()) as client:
        pertama = client.get('/katalog')
        ulang = client.get('/katalog', headers={'If-None-Match': pertama.headers['etag']})
        lemah = client.get('/katalog', headers={'If-None-Match': 'W/' + pertama.headers['etag']})
        assert pertama.json() == {'materi': ['Python', 'Web']}
        assert ulang.content == b''
        assert lemah.status_code == 304
        assert client.get('/katalog', headers={'If-None-Match': '"lama"'}).status_code == 200
        print(pertama.status_code)
        print(ulang.status_code)
        print('Body 304 kosong:', not ulang.content)

import base64
import binascii
import hashlib
import hmac
from typing import Annotated
from fastapi import FastAPI, HTTPException, Query
from fastapi.testclient import TestClient

DATA = tuple({'id': i, 'nama': f'Materi {i}'} for i in range(1, 6))


def create_app(secret: bytes):
    if not isinstance(secret, bytes) or len(secret) < 32:
        raise ValueError('Kunci minimal 32 byte; konfigurasi server, bukan input client.')
    app = FastAPI()

    def encode(last_id):
        payload = f'v1:{last_id}'.encode('ascii')
        signature = hmac.digest(secret, payload, hashlib.sha256)
        return base64.urlsafe_b64encode(payload + b'.' + signature).decode('ascii')

    def decode(token):
        try:
            raw = base64.b64decode(token, altchars=b'-_', validate=True)
            if len(raw) < 36 or raw[-33:-32] != b'.':
                raise ValueError('Format')
            payload, signature = raw[:-33], raw[-32:]
            if not hmac.compare_digest(hmac.digest(secret, payload, hashlib.sha256), signature):
                raise ValueError('Signature')
            versi, angka = payload.decode('ascii').split(':')
            if versi != 'v1' or not angka.isdecimal() or not 0 <= int(angka) <= 1000000000:
                raise ValueError('Isi')
            return int(angka)
        except (ValueError, UnicodeError, binascii.Error):
            raise HTTPException(status_code=400, detail='Cursor tidak valid') from None

    @app.get('/materi')
    def materi(limit: Annotated[int, Query(ge=1, le=3)] = 2,
               cursor: Annotated[str | None, Query(max_length=256)] = None):
        after = decode(cursor) if cursor is not None else 0
        kandidat = [item for item in DATA if item['id'] > after][:limit + 1]
        items = kandidat[:limit]
        lanjut = encode(items[-1]['id']) if len(kandidat) > limit else None
        return {'items': items, 'next_cursor': lanjut}

    return app


if __name__ == '__main__':
    # Hanya fixture lokal. Server nyata membaca secret dari konfigurasi rahasia.
    with TestClient(create_app(b'kunci-latihan-lokal-bukan-produksi-123456')) as client:
        ids = []
        cursor = None
        while True:
            params = {'limit': 2}
            if cursor is not None:
                params['cursor'] = cursor
            data = client.get('/materi', params=params).json()
            ids.extend(item['id'] for item in data['items'])
            cursor = data['next_cursor']
            if cursor is None:
                break
        assert client.get('/materi', params={'cursor': 'rusak'}).status_code == 400
        assert client.get('/materi', params={'limit': 0}).status_code == 422
        print(ids)
        print('Cursor akhir:', cursor)

export function ringkasan(nama, jumlah) {
  const bersih = nama.trim();
  if (!bersih || bersih.length > 80 || !Number.isInteger(jumlah) || jumlah < 1 || jumlah > 100) {
    throw new Error('Nama 1–80 karakter dan jumlah 1–100 diperlukan.');
  }
  return `${bersih}: ${jumlah} unit`;
}

import {ringkasan} from './web-modul-format.mjs';
const form = document.querySelector('#form');
const status = document.querySelector('#status');
form.addEventListener('submit', event => {
  event.preventDefault();
  try {
    status.textContent = ringkasan(document.querySelector('#nama').value,
      Number(document.querySelector('#jumlah').value));
  } catch (error) {
    status.textContent = error.message;
  }
